"""Grounded 28-Day New Zealand December Campervan Odyssey Dataset.

Covers the complete 4-week (28-day) route in December (austral summer):
- Arrival in Auckland (Day 1)
- Northernmost tip of the North Island: Cape Reinga / Te Rerenga Wairua (Days 2-5)
- North Island traverse: Coromandel, Hobbiton, Rotorua, Taupo, Tongariro, Wellington (Days 6-12)
- Cook Strait Campervan Ferry crossing from Wellington to Picton (Day 13)
- South Island traverse: Abel Tasman, Punakaiki, Glaciers, Wanaka, Queenstown, Milford Sound (Days 14-21)
- Southernmost tip of the South Island: Bluff & Slope Point, The Catlins & Dunedin (Days 22-23)
- East Coast & Southern Alps return: Moeraki, Aoraki / Mount Cook, Lake Tekapo to Christchurch (Days 24-28).
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional, Tuple

from app.schemas.itinerary_schemas import (
    CampsiteOption,
    DayItineraryPlan,
    FullOdysseyItinerary,
    MediaPhotoItem,
    MediaVideoItem,
)


def _build_day_dict(
    day_number: int,
    island: str,
    title: str,
    start_location: str,
    end_location: str,
    lat: float,
    lon: float,
    km: int,
    hrs: float,
    summary: str,
    highlights: List[str],
    places: List[str],
    tips: List[str],
    camp: Tuple[str, str, str, bool, float, List[str], str],
    weather: str,
    photo: Tuple[str, str, str],
    video: Tuple[str, str, str],
) -> Dict[str, Any]:
    """Constructs a canonical 28-day itinerary dictionary entry."""
    c_name, c_cat, c_reg, c_pow, c_rate, c_amen, c_adv = camp
    p_title, p_url, p_tag = photo
    v_title, v_id, v_dur = video
    return {
        "day_number": day_number,
        "date_label": f"Dec {day_number}",
        "island": island,
        "title": title,
        "start_location": start_location,
        "end_location": end_location,
        "latitude": lat,
        "longitude": lon,
        "drive_distance_km": km,
        "drive_duration_hours": hrs,
        "summary": summary,
        "must_do_highlights": highlights,
        "places_to_check_out": places,
        "noteworthy_campervan_tips": tips,
        "overnight_campsite": {
            "name": c_name,
            "category": c_cat,
            "region": c_reg,
            "powered_site_available": c_pow,
            "nightly_rate_nzd": c_rate,
            "amenities": c_amen,
            "booking_advice_december": c_adv,
        },
        "december_weather_note": weather,
        "photos": [
            {
                "title": p_title,
                "url": p_url,
                "credit": "Unsplash / Wikimedia NZ Curated",
                "location_tag": p_tag,
            }
        ],
        "videos": [
            {
                "title": v_title,
                "youtube_id": v_id,
                "embed_url": f"https://www.youtube-nocookie.com/embed/{v_id}",
                "watch_url": f"https://www.youtube.com/watch?v={v_id}",
                "duration_label": v_dur,
            }
        ],
    }


